/**
 * 改造自 shadcn 原装 base-lyra skeleton（https://ui.shadcn.com/r/styles/base-lyra/skeleton.json，MIT）。
 * 与上游的差异：
 * 1. 动效改由 `motion` 属性选预设（ADR 0021），骨架渲染 `data-motion`。缺省 `shimmer`：在 `bg-muted` 上扫过一道高光
 *    （基础层的 `animate-shimmer`，渐变配方见 `@developstack/tokens/base.css` 的 `@keyframes shimmer` 注释）。
 *    上游的 `animate-pulse` 换成预设 `pulse`；`none` 只是一块静态的 `bg-muted`。
 * 此外只有格式化（分号）。
 */
import { cn } from "cn";
import type * as React from "react";

/**
 * 骨架支持的动效预设（ADR 0021）。缺省 `shimmer`。
 * - `shimmer`：一道高光从左扫到右，1.4s 循环。
 * - `pulse`：不透明度 1 → 0.5 → 1 呼吸，2s 循环（上游的手感）。
 * - `none`：静态占位块。
 */
type SkeletonMotion = "none" | "pulse" | "shimmer";

const MOTION_CLASS: Record<SkeletonMotion, string> = {
  shimmer:
    "bg-linear-to-r from-transparent from-35% via-foreground/10 via-50% to-transparent to-65% animate-shimmer",
  pulse: "",
  none: "",
};

function Skeleton({
  className,
  motion = "shimmer",
  ...props
}: React.ComponentProps<"div"> & { motion?: SkeletonMotion }) {
  return (
    <div
      data-slot="skeleton"
      data-motion={motion === "none" ? undefined : motion}
      className={cn("rounded-none bg-muted", MOTION_CLASS[motion], className)}
      {...props}
    />
  );
}

export { Skeleton, type SkeletonMotion };
